use phx_sql_core::{parse_mysql_model,parse_postgresql_model,parse_sqlite_model,parse_sqlserver_model,project_table_graph};fn sig(m:&phx_sql_core::SqlModel)->(Vec<(String,usize,usize)>,Vec<(String,String)>){let g=project_table_graph(m);let mut n=g.nodes.into_iter().map(|x|(x.id,x.columns,x.degree)).collect::<Vec<_>>();n.sort();let mut e=g.edges.into_iter().map(|x|(x.source,x.target)).collect::<Vec<_>>();e.sort();(n,e)}#[test]fn parity(){let pg=parse_postgresql_model("pg",include_str!("../../../tests/fixtures/equivalent.postgresql.sql")).unwrap();let my=parse_mysql_model("my",include_str!("../../../tests/fixtures/equivalent.mysql.sql")).unwrap();let sq=parse_sqlite_model("sq",include_str!("../../../tests/fixtures/equivalent.sqlite.sql")).unwrap();let ss=parse_sqlserver_model("ss",include_str!("../../../tests/fixtures/equivalent.sqlserver.sql")).unwrap();assert_eq!(pg.tables.len(),3);assert_eq!(my.tables.len(),3);assert_eq!(sq.tables.len(),3);assert_eq!(ss.tables.len(),3);let x=sig(&pg);assert_eq!(sig(&my),x);assert_eq!(sig(&sq),x);assert_eq!(sig(&ss),x);}
